OVERLAYS = {'teaching_representations': '', 'slide_deck_v6_orchestrator': ''}
import asyncio,base64,hashlib,importlib.abc,importlib.util,json,os,sys,tempfile,zipfile
from pathlib import Path
course="afb29754-6842-437b-af1b-5866bfb53b41"
live=Path("/opt/lingzhi/state/backend-data")
raw=json.loads((live/"courses"/(course+".json")).read_text())
authoring_path=live/"teacher_lesson_authoring"/(course+".json")
before=authoring_path.read_bytes()
lesson=json.loads(before)["lessons"]["L1-1"]
plan=next(r for r in lesson["revisions"] if r["revision_id"]==lesson["working_revision_id"])
script=next(r for r in lesson["script_revisions"] if r["revision_id"]==lesson["working_script_revision_id"])
class OverlayLoader(importlib.abc.Loader):
 def __init__(self,name):self.name=name
 def create_module(self,spec):return None
 def exec_module(self,module):
  path="/opt/lingzhi/hackthon/backend/"+self.name+".py"
  module.__file__=path
  exec(compile(base64.b64decode(OVERLAYS[self.name]),path,"exec"),module.__dict__)
class OverlayFinder(importlib.abc.MetaPathFinder):
 def find_spec(self,name,path=None,target=None):
  if name in OVERLAYS:return importlib.util.spec_from_loader(name,OverlayLoader(name))
with tempfile.TemporaryDirectory(prefix="ppt-original-scope-proof-") as directory:
 os.environ["LINGZHI_DATA_DIR"]=directory+"/data"
 os.environ["LINGZHI_TASK_RUNTIME_MODE"]="read_only"
 sys.dont_write_bytecode=True
 sys.path.insert(0,"/opt/lingzhi/hackthon/backend")
 sys.meta_path.insert(0,OverlayFinder())
 from teacher_lesson_authoring import teacher_lesson_v6_source
 from teaching_representations import TeachingRepresentationRepository
 from slide_deck_v6_orchestrator import SlideDeckV6Orchestrator,SlideDeckV6CandidateRepository
 from slide_deck_v6 import PptManuscriptV1
 from ppt_teaching_manuscript import template_for_manuscript
 from representation_compiler import export_slide_deck_pptx
 doc,view,scope=teacher_lesson_v6_source(raw,lesson_unit_id="L1-1",plan_revision=plan,script_revision=script)
 manuscript=PptManuscriptV1.model_validate(lesson["ppt_manuscript"]["manuscript"])
 template=template_for_manuscript(manuscript)
 repo=TeachingRepresentationRepository(Path(directory)/"representations")
 scoped=repo.for_storage_scope(doc.course_id,scope)
 orchestrator=SlideDeckV6Orchestrator(representation_repository=scoped,candidate_repository=SlideDeckV6CandidateRepository(Path(directory)/"candidates"),progress_root=Path(directory)/"progress",require_pixel_audit=False)
 async def forbidden(*args,**kwargs):raise AssertionError("isolated proof must not call a model")
 async def run():
  return await asyncio.wait_for(orchestrator.build(task_id="original-isolated-scope-proof",document=doc,course_data=view,mode="teaching",theme=template.theme_id,story_planner=forbidden,visual_planner=forbidden,source_revision_provider=lambda:doc.document_revision,template_contract=template,confirmed_manuscript=manuscript,publish_result=True),240)
 result=asyncio.run(run())
 reopened=TeachingRepresentationRepository(Path(directory)/"representations").for_storage_scope(doc.course_id,scope)
 registry=reopened.load(doc.course_id)
 rep=next(r for r in registry.representations if r.representation_id==result["representation_id"])
 spec=next(s for s in registry.specs if s.spec_id==rep.spec_id)
 assert not repo.load(doc.course_id).representations
 assert doc.course_id==course and spec.course_id==course and all(b.course_id==course for b in spec.source_bindings)
 output=export_slide_deck_pptx(spec,Path(directory)/"proof.pptx")
 with zipfile.ZipFile(output) as z:
  import re
  pages=len([n for n in z.namelist() if re.fullmatch(r"ppt/slides/slide\d+\.xml",n)])
 assert pages==manuscript.page_count==12
 assert authoring_path.read_bytes()==before
 print(json.dumps({"event":"original_scope_proof_verified","pages":pages,"download_bytes":output.stat().st_size,"real_source_identity_preserved":True,"lecture_registry_readback":True,"production_records_unchanged":True}),flush=True)
